import StatisticsCards from '@/components/cards/StatisticsCards';
import GroupIcon from '@/components/icons/user/GroupIcon';
import MinusUserIcon from '@/components/icons/user/MinusUserIcon';
import TwoUsersIcon from '@/components/icons/user/TwoUsersIcon';
import UserRemoveIcon from '@/components/icons/UserRemoveIcon';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Card } from '@/types/statistics';
import { useEffect, useState } from 'react';

type Counts = { total: number; approved: number; rejected: number; pending: number };

/**
 * Self-service loans overview: counts for the logged-in user only (`mine=1` on the API).
 */
export default function LoanRequestsStatistics() {
    const [stats, setStats] = useState<Counts | null>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const res = await apiGet({
                    endpoint: endpoints.loan.dashboard,
                    queryParams: { mine: 1 },
                });
                const d = res.data?.data as Counts | undefined;
                if (!cancelled && d) {
                    setStats({
                        total: Number(d.total) || 0,
                        approved: Number(d.approved) || 0,
                        rejected: Number(d.rejected) || 0,
                        pending: Number(d.pending) || 0,
                    });
                }
            } catch {
                if (!cancelled) setStats(null);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, []);

    const cards: Card[] = [
        { text: 'طلباتي', num: stats?.total, percent: 0, icon: <GroupIcon /> },
        { text: 'مقبولة', num: stats?.approved, percent: 0, icon: <TwoUsersIcon /> },
        { text: 'مرفوضة', num: stats?.rejected, percent: 0, icon: <MinusUserIcon /> },
        { text: 'قيد المراجعة', num: stats?.pending, percent: 0, icon: <UserRemoveIcon /> },
    ];

    return <StatisticsCards cards={cards} numJustifyStart={true} />;
}
